function latestRecords(rows) {
  const best = new Map()
  for (const [id, email, updated] of rows) {
    const key = email.trim().toLowerCase()
    if (!key.includes('@')) continue
    const kept = best.get(key)
    if (!kept || updated > kept.updated || (updated === kept.updated && id > kept.id)) best.set(key, { id, updated })
  }
  return [...best.keys()].sort().map(key => [key, best.get(key).id])
}

