def latest_records(rows):
    best = {}
    for row_id, email, updated in rows:
        key = email.strip().lower()
        if "@" not in key:
            continue
        kept = best.get(key)
        if kept is None or (updated, row_id) > kept:
            best[key] = (updated, row_id)
    return [[key, best[key][1]] for key in sorted(best)]
